def normalize_amount(records):
    normalized = []
    for record in records:
        amount = record.get('amount', 0)
        if isinstance(amount, (int, float)):
            amount = max(0, min(1000000, amount))
        else:
            amount = 0
        normalized.append({'id': record.get('id'), 'amount': amount})
    return normalized

def dedupe_records(records):
    seen = set()
    unique_records = []
    for record in records:
        record_id = record.get('id')
        if record_id not in seen:
            seen.add(record_id)
            unique_records.append(record)
    return unique_records

def retry_failed(fn, attempts):
    for attempt in range(attempts):
        try:
            return fn()
        except Exception:
            if attempt == attempts - 1:
                raise
    return None

